"""Stock on hand and reservations held by open orders."""

from .errors import OutOfStock, ShopError


class Inventory:
    def __init__(self, on_hand=None, reserved=None):
        self.on_hand = dict(on_hand or {})
        self.reserved = dict(reserved or {})

    def available(self, sku):
        """Units that can still be reserved."""
        return self.on_hand.get(sku, 0) - self.reserved.get(sku, 0)

    def add_stock(self, sku, quantity):
        """Put quantity units on the shelf."""
        if quantity <= 0:
            raise ShopError("quantity must be positive")
        self.on_hand[sku] = self.on_hand.get(sku, 0) + quantity

    def reserve(self, sku, quantity):
        """Hold quantity units for an open order."""
        if quantity > self.available(sku):
            raise OutOfStock("%s: want %d, have %d" % (sku, quantity, self.available(sku)))
        self.reserved[sku] = self.reserved.get(sku, 0) + quantity

    def release(self, sku, quantity):
        """Give back a reservation."""
        self.reserved[sku] = max(0, self.reserved.get(sku, 0) - quantity)

    def commit(self, sku, quantity):
        """Turn a reservation into a sale: the units leave the shelf."""
        self.release(sku, quantity)
        self.on_hand[sku] = self.on_hand.get(sku, 0) - quantity

    def to_dict(self):
        """Serializable form."""
        return {"on_hand": dict(self.on_hand), "reserved": dict(self.reserved)}

    @classmethod
    def from_dict(cls, data):
        """Inverse of to_dict."""
        return cls(data.get("on_hand"), data.get("reserved"))

"""Order lifecycle: create, add/remove items, checkout, cancel."""

from .errors import OrderStateError, UnknownOrder, UnknownProduct
from .models import LineItem, Order
from .pricing import order_total


class OrderService:
    def __init__(self, catalog, inventory, orders=None):
        self.catalog = catalog
        self.inventory = inventory
        self.orders = {o.id: o for o in (orders or [])}

    def get(self, order_id):
        """Return the order or raise UnknownOrder."""
        try:
            return self.orders[order_id]
        except KeyError:
            raise UnknownOrder(order_id) from None

    def create_order(self, customer, created_at):
        """Start a new open order."""
        order = Order(id="o%d" % (len(self.orders) + 1), customer=customer, created_at=created_at)
        self.orders[order.id] = order
        return order

    def _open(self, order_id):
        order = self.get(order_id)
        if order.status != "open":
            raise OrderStateError("order %s is %s" % (order_id, order.status))
        return order

    def add_item(self, order_id, sku, quantity):
        """Add units of a product, reserving stock. Repeated SKUs merge into one line."""
        order = self._open(order_id)
        if sku not in self.catalog:
            raise UnknownProduct(sku)
        self.inventory.reserve(sku, quantity)
        item = order.find_item(sku)
        if item:
            item.quantity += quantity
        else:
            order.items.append(LineItem(sku, quantity, self.catalog[sku].price_cents))
        return order

    def remove_item(self, order_id, sku):
        """Drop a line and release its reservation."""
        order = self._open(order_id)
        item = order.find_item(sku)
        if item is None:
            raise UnknownProduct(sku)
        self.inventory.release(sku, item.quantity)
        order.items.remove(item)
        return order

    def checkout(self, order_id):
        """Pay for an open order: commit its stock and fix its total."""
        order = self._open(order_id)
        if not order.items:
            raise OrderStateError("order %s is empty" % order_id)
        for item in order.items:
            self.inventory.commit(item.sku, item.quantity)
        order.total_cents = order_total(order)
        order.status = "paid"
        return order

    def cancel(self, order_id):
        """Cancel an open order."""
        order = self._open(order_id)
        order.status = "cancelled"
        return order

"""JSON files for the catalog, orders and inventory."""

import json

from .errors import StorageError
from .inventory import Inventory
from .models import LineItem, Order, Product


def _read(path):
    try:
        with open(path) as f:
            return json.load(f)
    except (OSError, ValueError) as e:
        raise StorageError("%s: %s" % (path, e)) from None


def _write(path, data):
    with open(path, "w") as f:
        json.dump(data, f, indent=2, sort_keys=True)
        f.write("\n")


def load_catalog(path):
    """Return {sku: Product}."""
    return {
        p["sku"]: Product(p["sku"], p["name"], p["price_cents"], category=p.get("category"))
        for p in _read(path)
    }


def save_catalog(path, catalog):
    """Write {sku: Product} to path."""
    _write(path, [
        {"sku": p.sku, "name": p.name, "price_cents": p.price_cents, "category": p.category}
        for p in catalog.values()
    ])


def load_orders(path):
    """Return a list of Order."""
    orders = []
    for o in _read(path):
        items = [LineItem(i["sku"], i["quantity"], i["unit_price_cents"]) for i in o["items"]]
        orders.append(Order(o["id"], o["customer"], o["created_at"], items, o["status"], o["total_cents"]))
    return orders


def save_orders(path, orders):
    """Write a list of Order to path."""
    _write(path, [
        {
            "id": o.id,
            "customer": o.customer,
            "created_at": o.created_at,
            "items": [
                {"sku": i.sku, "quantity": i.quantity, "unit_price_cents": i.unit_price_cents}
                for i in o.items
            ],
            "status": o.status,
            "total_cents": o.total_cents,
        }
        for o in orders
    ])


def load_inventory(path):
    """Return an Inventory."""
    return Inventory.from_dict(_read(path))


def save_inventory(path, inventory):
    """Write an Inventory to path."""
    _write(path, inventory.to_dict())

